Q: How to hide and show array elements without jQuery A: <p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
    &lt;meta charset="UTF-8"&gt;
    &lt;title&gt;Title&lt;/title&gt;
&lt;/head&gt;
&lt;body&gt;


&lt;ul id="list"&gt;&lt;/ul&gt;


&lt;script&gt;
    list = document.getElementById('list');
    items = ['item 0', 'item 1', 'item 2'];
    for (x = 0; x &lt; items.length; x++) {
        li = document.createElement('li');
        li.appendChild(document.createTextNode(items[x]));
        list.appendChild(li);
        list.childNodes[x].setAttribute('onclick', 'hide(' + x + ')');
    }

    function hide(pos) {
        list.childNodes[pos].style.display = 'none';
    }


&lt;/script&gt;


&lt;/body&gt;
&lt;/html&gt;</code></pre>
</div>
</div>
</p>
